<div class="custom-main-title">
    <h1>Tax Invoice فاتورة ضريبية</h1>
</div>

<div class="ultra-compact-wrapper">

    <div class="border-bottom" style="padding: 1px 0;">
        <table class="tight-table">
            <tr>
                <td style="width: 15%; font-weight: bold;white-space: nowrap;">Customer Name :</td>
                <td style="text-align: center;"><b>{{ doc.customer_name }}</b></td>
                <td style="width: 15%; font-weight: bold; text-align: right;">: اسم العميل</td>
            </tr>
            <tr>
                <td style="font-weight: bold;">Address :</td>
                <td class="single-line-text">
                    {{ (doc.address_display or "").replace('<br>', ',').replace('\n', ',').split(',') | map('trim') | reject('none') | reject('equalto', '') | join(', ') | striptags }}
                </td>
                <td style="font-weight: bold; text-align: right;">: العنوان</td>
            </tr>
            <tr>
                <td style="font-weight: bold;">VAT Number :</td>
                <td style="text-align: center; font-weight: bold;">{{ doc.tax_id or "" }}</td>
                <td style="font-weight: bold; text-align: right;">: الرقم الضريبي</td>
            </tr>
        </table>
    </div>

    <div>
        <table class="tight-table">
            <tr>
                <!-- Row 1: Invoice No | Date -->
                <td style="width: 17.5%; font-weight: bold;" class="border-right nowrap-text">Invoice No :</td>
                <td style="width: 15.5%; text-align: center; font-weight: bold;" class="border-right nowrap-text">{{ doc.name }}</td>
                <td style="width: 17%; font-weight: bold; text-align: right;" class="border-right">:رقم الفاتورة</td>

                <td style="width: 15%; font-weight: bold;">Date :</td>
                <td style="width: 17.5%; text-align: center;">{{ doc.get_formatted("transaction_date") }}</td>
                <td style="width: 17.5%; font-weight: bold; text-align: right;">: التاريخ</td>
            </tr>

            <tr>
                <!-- Row 2: Due Date | Project -->
                <td style="font-weight: bold;" class="border-right nowrap-text">Delivery Date :</td>
                <td style="text-align: center;" class="border-right">{{ doc.get_formatted("delivery_date") }}</td>
                <td style="font-weight: bold; text-align: right;" class="border-right">: تاريخ الإستحقاق</td>

                <td style="font-weight: bold;">Project :</td>
                <td style="text-align: center;">{{ doc.project or "" }}</td>
                <td style="font-weight: bold; text-align: right;">: المشروع</td>
            </tr>

            <tr>
                <!-- Row 3: Customer PO | Blank -->
                <td style="font-weight: bold;" class="border-right nowrap-text">Customer P.O :</td>
