<div class="items-wrapper">
    <table class="items-table">
        <thead>
            <tr>
                <th style="width: 5%;">Sr<br>م</th>
                <th style="width: 20%;">Item<br>الصنف</th>
                <th style="width: 35%;">Description<br>الوصف</th>
                <th style="width: 10%;">Qty<br>الكمية</th>
                <th style="width: 15%;">Rate<br>السعر</th>
                <th style="width: 15%;" class="no-border-right">Amount<br>المبلغ</th>
            </tr>
        </thead>
        <tbody>
            {% for row in doc.items %}
            <tr>
                <td class="text-center">{{ row.idx }}</td>
                <td class="text-left"><b>{{ row.item_code }}</b></td>
                <td class="text-left">{{ row.description or "" }}</td>
                <td class="text-center">{{ row.qty }} {{ row.uom }}</td>
                <td class="text-right">{{ row.get_formatted("rate") }}</td>
                <td class="text-right no-border-right"><b>{{ row.get_formatted("amount") }}</b></td>
            </tr>
            {% endfor %}
        </tbody>
